/* ===================== BÀI 36 · Arbitration và tranh chấp bus ===================== */
/* Bài 36 · Arbitration và tranh chấp bus (AMTS-EMB-002-M09-L04, X86-036) — sinh bởi tools/author/mpu8086/l36.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P36=[{"label": "Ví dụ: INC ô nhớ dùng chung là đọc rồi ghi", "code": "; Ví dụ 1: INC ô nhớ dùng chung = 2 chu kỳ bus (đọc, ghi)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DW      0010H                   ; biến dùng chung với bus master khác\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        INC     dem                     ; đọc dem, rồi ghi dem + 1\n        MOV     AX, dem                 ; đọc lại: AX = 0011h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "INC dem (FF 06 00 00, 15 + EA 6 = 21 chu kỳ) có hai chu kỳ bus: đọc word 0010h ở 07120h rồi ghi 0011h. Giữa hai chu kỳ này, ở T4 của chu kỳ đọc, CPU có thể trao bus cho thiết bị đang giữ HOLD = 1. Đoán trước: lệnh MOV AX, dem có mấy chu kỳ bus dữ liệu? Đáp án 1 (dem ở địa chỉ chẵn)."}, {"label": "Ví dụ: khóa bằng LOCK XCHG và vùng găng", "code": "; Ví dụ 2: lấy khóa bằng LOCK XCHG, vùng găng, trả khóa\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkhoa    DB      0                       ; 0 = rảnh, 1 = có bus master đang giữ\ndem     DB      0                       ; chỉ sửa khi giữ khóa\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 1\nthu:\n        LOCK    XCHG AL, khoa           ; đọc khoa, ghi 1, bus bị khóa\n        TEST    AL, AL                  ; giá trị cũ = 0: lấy được khóa\n        JNZ     thu                     ; khác 0: đang bận, thử lại\n        INC     dem                     ; vùng găng\n        MOV     khoa, 0                 ; trả khóa: một chu kỳ ghi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "LOCK XCHG AL, khoa: mã máy F0 86 06 00 00, 17 + 6 + 2 = 25 chu kỳ. Đọc khoa = 0 và ghi 1 trong cùng một lệnh có khóa bus; TEST cho ZF = 1 nên JNZ không nhảy (4 chu kỳ). Vùng găng chỉ có INC dem; trả khóa bằng MOV khoa, 0 (một chu kỳ ghi). Đoán trước: sau lệnh XCHG, AL bằng bao nhiêu? Đáp án 00h."}, {"label": "Bẫy: kiểm tra rồi đặt khóa bằng hai lệnh", "code": "; Ví dụ 3 (bẫy): kiểm tra rồi đặt khóa bằng hai lệnh riêng\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkhoa    DB      0\ndem     DB      0\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, khoa                ; đọc khoa (một chu kỳ bus)\n        TEST    AL, AL\n        JNZ     ban                     ; khóa bận\n        MOV     khoa, 1                 ; ghi ở lệnh khác: có thể bị chen\n        INC     dem\n        MOV     khoa, 0\nban:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: chạy một mình thì đúng (khoa = 0, dem = 1), nhưng đọc khoa ở lệnh 3 và ghi khoa ở lệnh 6 là hai lệnh riêng: giữa chúng có TEST, JNZ và ít nhất một lần CPU tới T4 với bus rảnh để trao. Một master khác cũng đọc được khoa = 0 rồi cả hai cùng vào vùng găng. Sửa: Ví dụ 2. Đoán trước: lệnh JNZ ban có nhảy không? Đáp án không (AL = 0)."}, {"label": "Ví dụ: khóa bận, thử 3 lần rồi báo bận", "code": "; Ví dụ 4: khóa đang bận, thử tối đa 3 lần rồi báo bận\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkhoa    DB      1                       ; giả định: bus master khác giữ khóa\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 3                   ; số lần thử\nthu:\n        MOV     AL, 1\n        LOCK    XCHG AL, khoa\n        TEST    AL, AL\n        JZ      duoc                    ; giá trị cũ 0: lấy được khóa\n        LOOP    thu\n        MOV     DL, 'B'                 ; hết 3 lần: báo bận\n        JMP     inra\nduoc:\n        MOV     khoa, 0                 ; (không tới đây ở ví dụ này)\n        MOV     DL, 'K'\ninra:\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "khoa = 1 (giả định: master khác đang giữ và không trả trong lúc chạy). Mỗi lần thử: XCHG đọc 1 và ghi lại 1 (không làm hỏng khóa của người khác), JZ không nhảy, LOOP quay lại. Sau 3 lần, in B. Tổng 286 chu kỳ. Đoán trước: sau vòng lặp, khoa bằng bao nhiêu? Đáp án 1."}, {"label": "Lỗi: hai master cùng cộng, mất một lần cập nhật", "code": "; Ví dụ 5 (lỗi): hai master cùng cộng 1, mất một lần\n; Giả lập trên một CPU: AX của master A, BX của B\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DW      10\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, dem                 ; A đọc 10\n        MOV     BX, dem                 ; B đọc 10 (A chưa kịp ghi)\n        INC     AX                      ; A tính 11\n        INC     BX                      ; B tính 11\n        MOV     dem, AX                 ; A ghi 11\n        MOV     dem, BX                 ; B ghi 11: lần cộng của A bị mất\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý, giả lập hai master trên một CPU: AX là thanh ghi của A, BX của B. Thứ tự chu kỳ bus: A đọc 10, B đọc 10, A ghi 11, B ghi 11. Kết quả 11 thay vì 12: mất một lần cập nhật dù không có xung đột bus nào. Đoán trước: dem cuối cùng bằng bao nhiêu? Đáp án 11."}, {"label": "Ví dụ: sửa bằng LOCK INC", "code": "; Ví dụ 6: sửa ví dụ 5, mỗi master cộng bằng một lệnh LOCK INC\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DW      10\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        LOCK    INC dem                 ; A: đọc 10, ghi 11, bus bị khóa\n        LOCK    INC dem                 ; B: đọc 11, ghi 12\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Sửa ví dụ 5: mỗi master cộng bằng một lệnh LOCK INC dem (F0 FF 06 00 00, 15 + 6 + 2 = 23 chu kỳ). Chu kỳ đọc và chu kỳ ghi của một lệnh không bị xen vào, nên dem = 12. Ở chế độ maximum (Hình 36.2), chân LOCK thấp trong cả hai chu kỳ bus. Đoán trước: lệnh LOCK INC thứ hai đọc giá trị nào? Đáp án 000Bh."}];
const sim36=makeX86Sim(document.getElementById("x86-l36"),{id:"s36",presets:P36,file:"BAI36.ASM"});
makeX86Ex(document.getElementById("ex-l36"),sim36,[{"t": "Tìm xung đột bus", "d": "Mỗi phím 0–3 là một xung nhịp trong bản ghi tín hiệu (tối đa 20 phím), kết thúc bằng Enter: bit 1 là HLDA, bit 0 cho biết thiết bị DMA có đang lái bus không. Mã 1 (HLDA = 0 mà thiết bị lái bus) là xung đột: CPU chưa nhả bus. Ghi số xung nhịp xung đột vào soX và chỉ số (từ 0) của xung nhịp xung đột đầu tiên vào dau (giữ FFh nếu không có). Code mẫu đã có phần in “soX dau” (in dấu - nếu không có xung đột).", "start": "; Bài tập 1: tìm xung đột bus trong bản ghi tín hiệu\n; Mỗi phím 0-3 là một xung nhịp: bit 1 = HLDA, bit 0 = thiết bị DMA lái bus.\n; Mã 1 (HLDA = 0 mà thiết bị lái bus) là xung đột. Kết thúc bằng Enter.\n; Ghi số xung nhịp xung đột vào soX, chỉ số xung nhịp xung đột đầu tiên vào dau.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nsoX     DB      0                       ; số xung nhịp xung đột\ndau     DB      0FFH                    ; xung nhịp xung đột đầu (FFh = chưa có)\nk       DB      0                       ; chỉ số xung nhịp đang đọc, từ 0\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, 13                  ; Enter: hết bản ghi\n        JE      inkq\n; Viết code ở đây: nếu AL là mã '1' thì tăng soX,\n; ghi k vào dau nếu đây là xung đột đầu tiên; luôn tăng k\n        JMP     doc\ninkq:\n        MOV     AL, soX                 ; in \"soX dau\" (dau '-': không xung đột)\n        XOR     AH, AH\n        CALL    INSO\n        MOV     AH, 02H\n        MOV     DL, ' '\n        INT     21H\n        CMP     dau, 0FFH\n        JE      khong\n        MOV     AL, dau\n        XOR     AH, AH\n        CALL    INSO\n        JMP     het\nkhong:\n        MOV     AH, 02H\n        MOV     DL, 2DH                 ; mã ASCII của '-'\n        INT     21H\nhet:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; INSO: in AX ở dạng thập phân\nINSO:\n        MOV     BX, 10\n        XOR     CX, CX\nis1:\n        XOR     DX, DX\n        DIV     BX\n        PUSH    DX\n        INC     CX\n        TEST    AX, AX\n        JNZ     is1\n        MOV     AH, 02H\nis2:\n        POP     DX\n        ADD     DL, '0'\n        INT     21H\n        LOOP    is2\n        RET\n        END     MAIN\n", "tests": [{"in": "0133210", "out": "2 1", "mem": [{"at": "soX", "bytes": [2]}, {"at": "dau", "bytes": [1]}]}, {"in": "0233320", "out": "0 -", "mem": [{"at": "soX", "bytes": [0]}, {"at": "dau", "bytes": [255]}]}, {"in": "1", "out": "1 0", "mem": [{"at": "soX", "bytes": [1]}, {"at": "dau", "bytes": [0]}]}, {"in": "00000000000000000001", "out": "1 19", "mem": [{"at": "soX", "bytes": [1]}, {"at": "dau", "bytes": [19]}]}, {"in": "11111", "out": "5 0", "mem": [{"at": "soX", "bytes": [5]}, {"at": "dau", "bytes": [0]}]}, {"in": "3333222200001", "out": "1 12", "mem": [{"at": "soX", "bytes": [1]}, {"at": "dau", "bytes": [12]}]}, {"in": "0123012301230123", "out": "4 1", "mem": [{"at": "soX", "bytes": [4]}, {"at": "dau", "bytes": [1]}]}, {"in": "2222", "out": "0 -", "mem": [{"at": "soX", "bytes": [0]}, {"at": "dau", "bytes": [255]}]}]}, {"t": "HOLD/HLDA từng xung nhịp", "d": "Nhập dãy HOLD (mỗi phím 0 hoặc 1 là một xung nhịp, tối đa 20), kết thúc bằng Enter. Theo đúng mô hình của bài (mục 36.2): CPU giữ bus chạy liền các chu kỳ T1–T4, chỉ xét HOLD ở T4; HOLD = 1 ở T4 thì từ xung nhịp sau CPU nhả bus; khi đã nhả, HOLD = 1 là thiết bị lái bus, HOLD = 0 là bus trống một xung nhịp rồi CPU bắt đầu T1. In mỗi xung nhịp một chữ (C = CPU, D = thiết bị, - = không ai), xuống dòng, rồi in số xung nhịp thiết bị lái bus (ghi vào soD).", "start": "; Bài tập 2: HOLD/HLDA từng xung nhịp theo mô hình của bài\n; Nhập dãy HOLD (0/1), mỗi phím một xung nhịp, kết thúc bằng Enter.\n; In ai lái bus ở mỗi xung nhịp (C = CPU, D = thiết bị, - = không ai),\n; xuống dòng, rồi in số xung nhịp thiết bị lái bus (soD).\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\npha     DB      0                       ; CPU giữ bus: 0-3 ứng với T1-T4\nnha     DB      0                       ; 1 = CPU đã nhả bus (HLDA = 1)\nsoD     DB      0                       ; số xung nhịp thiết bị lái bus\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, 13                  ; Enter: hết dãy\n        JE      xong\n; Viết code ở đây theo luật của mô hình (mục 36.2).\n; Hiện tại: luôn in C (CPU giữ bus mãi), chưa đúng.\n        MOV     AH, 02H\n        MOV     DL, 'C'\n        INT     21H\n        JMP     doc\nxong:\n        MOV     AH, 02H                 ; xuống dòng rồi in soD\n        MOV     DL, 13\n        INT     21H\n        MOV     DL, 10\n        INT     21H\n        MOV     AL, soD\n        XOR     AH, AH\n        CALL    INSO\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; INSO: in AX ở dạng thập phân\nINSO:\n        MOV     BX, 10\n        XOR     CX, CX\nis1:\n        XOR     DX, DX\n        DIV     BX\n        PUSH    DX\n        INC     CX\n        TEST    AX, AX\n        JNZ     is1\n        MOV     AH, 02H\nis2:\n        POP     DX\n        ADD     DL, '0'\n        INT     21H\n        LOOP    is2\n        RET\n        END     MAIN\n", "tests": [{"in": "0011111000", "out": "CCCCDDD-CC\r\n3", "mem": [{"at": "soD", "bytes": [3]}]}, {"in": "1111111", "out": "CCCCDDD\r\n3", "mem": [{"at": "soD", "bytes": [3]}]}, {"in": "0100000000", "out": "CCCCCCCCCC\r\n0", "mem": [{"at": "soD", "bytes": [0]}]}, {"in": "0001100011", "out": "CCCCD-CCCC\r\n1", "mem": [{"at": "soD", "bytes": [1]}]}, {"in": "0001000100110", "out": "CCCC-CCCCCCCC\r\n0", "mem": [{"at": "soD", "bytes": [0]}]}, {"in": "00000001111000", "out": "CCCCCCCCDDD-CC\r\n3", "mem": [{"at": "soD", "bytes": [3]}]}, {"in": "00011111111111111111", "out": "CCCCDDDDDDDDDDDDDDDD\r\n16", "mem": [{"at": "soD", "bytes": [16]}]}, {"in": "0", "out": "C\r\n0", "mem": [{"at": "soD", "bytes": [0]}]}]}, {"t": "Giữ khóa ngắn nhất", "d": "Phím đầu là trạng thái khoa lúc bắt đầu (0 rảnh; 1 = một bus master khác đang giữ và không trả trong lúc chương trình chạy). Các phím sau là chữ số 0–9 (tối đa 16), kết thúc bằng Enter. Cộng tổng các chữ số vào tong và số chữ số vào dem (hai biến dùng chung đã có sẵn giá trị 1000 và 5 trong code mẫu: cộng thêm, giữ nguyên khai báo), chỉ trong lúc giữ khóa; lấy khóa bằng LOCK XCHG, thử tối đa 3 lần; xong thì trả khóa và in K; khóa bận cả 3 lần thì in B, tong và dem không đổi. Code mẫu đúng nhưng lấy và trả khóa ở mỗi chữ số. Viết lại để đạt giới hạn chu kỳ và byte mã.", "start": "; Bài tập 3: cộng dồn vào biến dùng chung, giữ khóa ngắn nhất\n; Phím đầu: trạng thái khoa lúc bắt đầu (0 rảnh, 1 = bus master khác đang giữ).\n; Các phím sau: chữ số 0-9 (tối đa 16), kết thúc bằng Enter.\n; Cộng tổng các chữ số vào tong, số chữ số vào dem, chỉ khi giữ khóa;\n; lấy khóa bằng LOCK XCHG, thử tối đa 3 lần; in K nếu xong, B nếu khóa bận\n; (khi bận: tong, dem không đổi). Trả khóa khi xong.\n; Code mẫu đúng nhưng lấy và trả khóa ở MỖI chữ số: chậm.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DW      1000                    ; dữ liệu dùng chung\ndem     DB      5                       ; dữ liệu dùng chung\nkhoa    DB      0                       ; 0 = rảnh\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; giả lập: bus master khác để lại khóa\n        INT     21H\n        SUB     AL, '0'\n        MOV     khoa, AL\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        CMP     AL, 13\n        JE      xong\n        SUB     AL, '0'\n        MOV     BL, AL                  ; BL = chữ số\n        MOV     CX, 3\nthu:\n        MOV     AL, 1\n        LOCK    XCHG AL, khoa\n        TEST    AL, AL\n        JZ      duoc\n        LOOP    thu\n        JMP     ban                     ; 3 lần đều bận\nduoc:\n        XOR     BH, BH\n        ADD     tong, BX\n        INC     dem\n        MOV     khoa, 0                 ; trả khóa\n        JMP     doc\nxong:\n        MOV     DL, 'K'\n        JMP     inra\nban:\n        MOV     DL, 'B'\ninra:\n        MOV     AH, 02H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "01234", "out": "K", "mem": [{"at": "tong", "bytes": [242, 3]}, {"at": "dem", "bytes": [9]}, {"at": "khoa", "bytes": [0]}]}, {"in": "09999999999999999", "out": "K", "mem": [{"at": "tong", "bytes": [120, 4]}, {"at": "dem", "bytes": [21]}, {"at": "khoa", "bytes": [0]}]}, {"in": "11234", "out": "B", "mem": [{"at": "tong", "bytes": [232, 3]}, {"at": "dem", "bytes": [5]}, {"at": "khoa", "bytes": [1]}]}, {"in": "05", "out": "K", "mem": [{"at": "tong", "bytes": [237, 3]}, {"at": "dem", "bytes": [6]}, {"at": "khoa", "bytes": [0]}]}, {"in": "00000", "out": "K", "mem": [{"at": "tong", "bytes": [232, 3]}, {"at": "dem", "bytes": [9]}, {"at": "khoa", "bytes": [0]}]}, {"in": "19999999999999999", "out": "B", "mem": [{"at": "tong", "bytes": [232, 3]}, {"at": "dem", "bytes": [5]}, {"at": "khoa", "bytes": [1]}]}, {"in": "0", "out": "K", "mem": [{"at": "tong", "bytes": [232, 3]}, {"at": "dem", "bytes": [5]}, {"at": "khoa", "bytes": [0]}]}, {"in": "08070605040302010", "out": "K", "mem": [{"at": "tong", "bytes": [12, 4]}, {"at": "dem", "bytes": [21]}, {"at": "khoa", "bytes": [0]}]}], "perf": {"cycles": 1900, "bytes": 84}}]);
