makeX86Hold(document.getElementById("hold-l36"),{scenarios:[{"label": "DMA xin bus, CPU nhả sau T4", "hold": "0011111000", "note": "HOLD lên ở T3 (xung nhịp 2). CPU chạy nốt T4 rồi nhả bus: thiết bị lái 3 xung nhịp (4–6), hạ HOLD ở xung nhịp 7 → bus trống 1 xung nhịp, CPU bắt đầu T1 ở xung nhịp 8. Kết quả CCCCDDD-CC."}, {"label": "HOLD lên ngay sau T4: chờ hết chu kỳ sau", "hold": "000011111110000", "note": "HOLD lên ở xung nhịp 4, đúng lúc CPU vừa bắt đầu T1 của chu kỳ mới. Theo mô hình, CPU chỉ xét HOLD ở T4 nên thiết bị chờ 4 xung nhịp (4–7) rồi mới được bus ở xung nhịp 8. Kết quả CCCCCCCCDDD-CCC."}, {"label": "Xung HOLD ngắn bị bỏ lỡ", "hold": "0110000000", "note": "HOLD chỉ lên ở T2 và T3 rồi xuống trước T4: CPU không thấy, không nhả bus. Thiết bị phải giữ HOLD cho tới khi thấy HLDA = 1. Kết quả CCCCCCCCCC."}, {"label": "Lỗi: thiết bị không chờ HLDA", "hold": "0011111000", "rogue": "0011111000", "note": "Thiết bị lái bus ngay khi đưa HOLD = 1 (xung nhịp 2), không chờ HLDA. Ở xung nhịp 2 và 3, CPU vẫn đang ở T3, T4: hai master cùng lái bus, 2 xung nhịp xung đột (X)."}, {"label": "Lỗi: thiết bị hạ HOLD nhưng chưa thả nổi bus", "hold": "0001110000", "rogue": "0000001100", "note": "Thiết bị hạ HOLD ở xung nhịp 6 nhưng vẫn lái bus ở xung nhịp 6 và 7. Xung nhịp 6 bus đáng lẽ trống; xung nhịp 7 CPU bắt đầu T1: xung đột 1 xung nhịp. Phải thả nổi bus trước khi hạ HOLD."}, {"label": "DMA giữ bus lâu: CPU mất bus 12 xung nhịp", "hold": "00011111111111110000", "note": "Một khối DMA dài: thiết bị lái bus từ xung nhịp 4 tới 15. Trong thời gian đó CPU chỉ chạy được lệnh đã có trong hàng đợi (mô hình này không vẽ phần đó). Kết quả CCCC + 12 D + - + CCC."}]});

makeQuiz("quiz36","score36",[{"q": "Ở chế độ minimum, thiết bị DMA đưa HOLD = 1 đúng lúc 8086 đang ở T2 của một chu kỳ ghi bộ nhớ. 8086 làm gì?", "o": ["Dừng ngay chu kỳ ghi ở T2 và đưa HLDA = 1 ở xung nhịp sau", "Bỏ qua HOLD vì chỉ xét HOLD khi đang ở trạng thái nghỉ", "Đưa HLDA = 1 nhưng vẫn tiếp tục lái bus tới hết lệnh", "Chạy nốt chu kỳ ghi tới T4 rồi mới đưa HLDA = 1 và thả nổi bus"], "a": 3, "e": "8086 không cắt ngang một chu kỳ bus: nó trả lời HLDA ở T4 (hoặc Ti) và thả nổi bus cùng lúc. Cắt giữa chu kỳ ghi sẽ để bộ nhớ nhận dữ liệu dở dang."}, {"q": "Theo mô hình của bài, dãy HOLD theo từng xung nhịp là <code>0011110000<\/code>. Chuỗi “ai lái bus” là gì?", "o": ["CCDDDD-CCC", "CCCCDDDD-C", "CCCCDD-CCC", "CCCCCCCCCC"], "a": 2, "e": "HOLD = 1 ở T4 (xung nhịp 3) → nhả bus. Xung nhịp 4, 5 HOLD còn 1 → D D; xung nhịp 6 HOLD = 0 → bus trống (-); từ xung nhịp 7 CPU chạy T1, T2, T3. CPU không nhả bus ở T3 (xung nhịp 2)."}, {"q": "Một bản ghi tín hiệu có HLDA = 0 nhưng bộ đệm đầu ra của thiết bị DMA đang bật (thiết bị lái bus). Chuyện gì xảy ra?", "o": ["Không sao: CPU tự thả nổi bus khi thấy thiết bị đang lái bus", "Chỉ chậm hơn vì CPU chèn thêm trạng thái chờ", "Xung đột bus: hai master cùng lái, mức điện sai, dòng lớn", "Thiết bị nhận được bus sớm hơn nên DMA nhanh hơn"], "a": 2, "e": "HLDA = 0 nghĩa là CPU chưa nhả bus và vẫn có thể lái. Thiết bị chỉ được lái khi HLDA = 1. CPU không tự phát hiện xung đột."}, {"q": "Hai bộ xử lý dùng chung biến dem và cùng chạy đoạn code sau. Vì sao dem có thể chỉ tăng 1 thay vì 2?<pre class=\"mp-asm\">        MOV     AX, dem\n        INC     AX\n        MOV     dem, AX<\/pre>", "o": ["Cả hai đọc giá trị cũ trước khi bên kia ghi, rồi ghi đè", "INC AX chỉ cộng vào byte thấp nên mất phần nhớ", "Phân xử bus làm mất một chu kỳ ghi khi đổi chủ", "MOV dem, AX ghi vào địa chỉ lẻ nên cần hai chu kỳ bus"], "a": 0, "e": "Phân xử bus chỉ bảo đảm mỗi chu kỳ bus có một master; giữa các lệnh, master kia vẫn chen vào được. Ví dụ 5 cho thấy thứ tự đọc 10, đọc 10, ghi 11, ghi 11. Sửa bằng LOCK INC dem hoặc khóa bằng LOCK XCHG."}, {"q": "Ở chế độ maximum, 8087 phát xung xin trên RQ/GT0 trong khi 8086 đang chạy <code>LOCK XCHG AL, khoa<\/code>. Khi nào 8087 được bus?", "o": ["Ngay T4 của chu kỳ đọc khoa", "Sau khi lệnh có tiền tố LOCK chạy xong", "Ngay xung nhịp sau xung xin", "Không bao giờ, vì RQ/GT0 bị tắt khi có LOCK"], "a": 1, "e": "Một điều kiện để 8086 trao bus qua RQ/GT là không đang chạy lệnh có tiền tố LOCK. Vì vậy chu kỳ đọc và ghi của XCHG không bị xen vào; 8087 được bus sau lệnh đó."}]);

